initScript:
await ManagerApi.ready();
const workspaceRoot = (await utils.postForm(ManagerApi.url('get_root'), {})).trim().replace(/\/$/, '');
const managerDir = new URL(window.SHV_MANAGER_URL).pathname.replace(/\/$/, '').split('/').pop();
const baseDir = workspaceRoot + '/' + managerDir + '/.temp';
const testFileName = 'api-test.txt';
return {
  baseDir, testFileName,
  createFileUrl: ManagerApi.url('create_file'),
  scanFileUrl: ManagerApi.url('scan_file'),
  writeFileUrl: ManagerApi.url('write_file'),
  readFileUrl: ManagerApi.url('read_file'),
  renameFileUrl: ManagerApi.url('rename_file'),
  deleteFileUrl: ManagerApi.url('delete_file'),
  message: 'init done: ' + baseDir
};

finallyScript:
const names = ['api-test.txt', 'api-test-renamed.txt'];
for (const n of names) {
  try { await utils.postForm(deleteFileUrl, { path: baseDir + '/' + n }); } catch (_) {}
}
return { message: 'cleanup done' };

tests.scriptText:
const text = await utils.postForm(createFileUrl, { dir: baseDir, name: testFileName });
const m = text.match(/\[(.+?)\]/);
assert(m && m[1], 'create: parse fail');
return { filePath: m[1], message: 'created=' + m[1] };

const text = await utils.postForm(scanFileUrl, { path: baseDir });
const arr = JSON.parse(text || '[]');
assert(Array.isArray(arr), 'scan: result not array');
const names = arr.map(x => x.name);
assert(names.includes(utils.basename(filePath)), 'scan: file missing');
return { message: 'scan ok' };

await utils.postForm(writeFileUrl, { path: filePath, content: 'hello test' });
const text = await utils.postForm(readFileUrl, { path: filePath });
assert(text.includes('hello test'), 'write: verify read mismatch');
return { message: 'written + verified=' + filePath };

const text = await utils.postForm(readFileUrl, { path: filePath });
assert(text.includes('hello test'), 'read: content mismatch');
return { message: 'read ok' };

const text = await utils.postForm(renameFileUrl, { path: filePath, name: 'api-test-renamed.txt' });
const m = text.match(/to \[(.+?)\]/);
assert(m && m[1], 'rename: parse fail');
const arr = JSON.parse((await utils.postForm(scanFileUrl, { path: baseDir })) || '[]');
assert(Array.isArray(arr), 'rename: scan result not array');
const names = arr.map(x => x.name);
assert(!names.includes(utils.basename(filePath)), 'rename: old name still exists');
assert(names.includes(utils.basename(m[1])), 'rename: new name missing');
return { renamedPath: m[1], message: 'renamed + verified=' + m[1] };

await utils.postForm(deleteFileUrl, { path: renamedPath });
const arr = JSON.parse((await utils.postForm(scanFileUrl, { path: baseDir })) || '[]');
assert(Array.isArray(arr), 'delete: scan result not array');
const names = arr.map(x => x.name);
assert(!names.includes(utils.basename(renamedPath)), 'delete: renamed still exists');
return { message: 'deleted + verified' };
